def py(x):
    return x.to_py() if hasattr(x, "to_py") else x

def first(name):
    try:
        return py(_(name).first().json) or {}
    except Exception:
        return {}

def all_rows(name):
    try:
        return [py(i.json) for i in _(name).all()]
    except Exception:
        return []

cfg = first("Test Settings")
t1, t2, t3, t5 = first("T1 Agent"), first("T2 Booking"), first("T3 Stripe Paid"), first("T5 Driver Cash Command")
ref = t2.get("booking_reference")
jobs = all_rows("Read Jobs")
ledger = [py(i.json) for i in _input.all()]

checks = []
def check(part, name, ok, detail=""):
    checks.append({"part": part, "test": name, "result": "PASS" if ok else "FAIL", "detail": str(detail)[:160]})

reply = str(t1.get("reply") or "")
check("Part 1", "AI agent answered the customer", bool(reply) and "error" not in t1, reply or t1.get("error"))
check("Part 1", "Answer uses real tour prices (39/49/220)", any(p in reply for p in ("39", "49", "220")), reply[:100])

check("Part 2", "Booking created with reference", bool(ref), ref or t2.get("error"))
check("Part 2", "Server-side price is correct (2 x 49 = 98)", t2.get("amount_eur") == 98, t2.get("amount_eur"))
check("Part 2", "Payment link returned", bool(t2.get("payment_link")), t2.get("payment_link"))
check("Part 2", "Stripe 'paid' webhook acknowledged", t3.get("received") is True, t3 or "no response")

job = next((r for r in jobs if ref and r.get("BookingRef") == ref), None)
check("Part 3", "Paid job saved in 'Jobs' sheet", job is not None, job.get("Status") if job else "row not found")
check("Part 3", "Job status is OPEN (waiting for a driver)", bool(job) and str(job.get("Status", "")).upper() == "OPEN", job.get("Status") if job else "")

row = next((r for r in ledger if ref and r.get("BookingRef") == ref and str(r.get("Method")).lower() == "cash"), None)
check("Part 4", "Cash payment written to 'CashLedger' sheet", row is not None, row if row else "row not found")
try:
    amt_ok = bool(row) and float(str(row.get("Amount")).replace(",", ".")) == 98.0
except ValueError:
    amt_ok = False
check("Part 4", "Ledger amount is 98", amt_ok, row.get("Amount") if row else "")

failed = [x for x in checks if x["result"] == "FAIL"]
lines = [("✅" if x["result"] == "PASS" else "❌") + f" {x['part']}: {x['test']}" for x in checks]
summary = f"E2E test {'PASSED' if not failed else 'FAILED'}: {len(checks) - len(failed)}/{len(checks)} checks OK (booking {ref})"

if failed and cfg.get("strict"):
    # scheduled run: raise so the Error Handler workflow emails you
    raise Exception(summary + " | failed: " + "; ".join(f"{x['part']} - {x['test']}" for x in failed))

return [{"json": {"summary": summary, "passed": len(checks) - len(failed), "failed": len(failed),
                  "report": "\n".join(lines), "checks": checks, "booking_ref": ref}}]
